// Unifica las tres ramas en un contrato unico. Devuelve HTML, no items:
// quien extrae las notas es el consumidor, no este ladrillo.
// $itemIndex, NO .first(): n8n manda todos los items en UNA sub-ejecucion, asi
// que con .first() los N resultados se creen el primer dominio. Se vio en la
// primera prueba: 9dejulio.gob.ar aparecia dos veces con diagnosticos distintos.
const _entradas = $('Entrada').all();
const req = (_entradas[$itemIndex] || _entradas[0] || { json: {} }).json;
const inp = $json;
const transporte = req.transporte || 'directo';

// Tope de memoria. Medido en la Fase 3: 35 dominios con HTML retienen ~21 MB en
// el nodo HTTP y 70 matan el proceso. Una home puede pesar megas, asi que se
// corta y se avisa con `truncado` en vez de arrastrar todo y morir.
const TOPE = 800 * 1024;

function host(u){ try { return (String(u).split('//')[1]||String(u)).split('/')[0].replace(/^www\./,'').toLowerCase(); } catch(e){ return null; } }

const r = {
  dominio_norm: req.dominio_norm || host(req.url || ''),
  url: req.url || null,
  transporte,
  http_status: null,
  diagnostico: null,
  html: null,
  bytes: 0,
  truncado: false
};

// --- de donde sale el cuerpo y el status, segun la rama ---
let body = inp.data ?? inp.body ?? (typeof inp === 'string' ? inp : '');
if (typeof body !== 'string') body = JSON.stringify(body);

const headers = inp.headers || {};
// El worker en modo raw siempre responde 200 y pone el status del medio aca.
const upstream = headers['x-upstream-status'] ?? headers['X-Upstream-Status'] ?? null;
let status = upstream !== null ? parseInt(upstream, 10) : (inp.statusCode ?? inp.status ?? null);

// El proxy pudo caer en su catch y devolver JSON en vez de texto, o el de AWS
// pudo ignorar raw=1 y mandar el contrato con items. Los dos casos son JSON.
if (body && body.trimStart().startsWith('{')) {
  let j = null;
  try { j = JSON.parse(body); } catch(e) { j = null; }
  if (j && typeof j === 'object') {
    if (Array.isArray(j.items)) {
      r.http_status = j.upstream_status ?? status;
      r.diagnostico = 'sin_raw';
      return { json: r };
    }
    if (j.ok === false || j.diagnostico) {
      r.http_status = j.upstream_status ?? status;
      // error_red no esta en el vocabulario del resto; se aplana a timeout.
      r.diagnostico = (j.diagnostico === 'error_red') ? 'timeout' : (j.diagnostico || 'timeout');
      return { json: r };
    }
  }
}

if (inp.error || status === null || status === 0) { r.http_status = status; r.diagnostico = 'timeout'; return { json: r }; }

r.http_status = status;
if (status === 403 || status === 401) { r.diagnostico = 'bloqueado'; return { json: r }; }
if (status === 404) { r.diagnostico = 'no_existe'; return { json: r }; }
if (status === 429) { r.diagnostico = 'rate_limit'; return { json: r }; }
// 405/400: el sitio rechaza el pedido tal como se lo hacemos. NO es 'vacio' —
// visto en buscojobs.com.ar, que devolvia 405 y quedaba como 'pagina sin links'.
// Distinguirlo importa: uno se arregla cambiando el pedido, el otro no se arregla.
if (status === 405 || status === 400) { r.diagnostico = 'metodo_rechazado'; return { json: r }; }
if (status >= 500) { r.diagnostico = 'caido'; return { json: r }; }

r.bytes = body.length;
if (r.bytes > TOPE) { body = body.slice(0, TOPE); r.truncado = true; }
r.html = body;

// 'ok' = vino algo de donde se puedan sacar notas. Sin un solo <a href> no hay
// nada que extraer, y eso es distinto de un 200 con la pagina vacia.
r.diagnostico = /<a\s[^>]*href/i.test(body) ? 'ok' : 'vacio';
return { json: r };
